 void addBlock(float x,float y,float width,float font,CharSequence value){Block block=new Block(x,y,width,font);EditText editor=new EditText(host);block.editor=editor;editor.setTextColor(0xff111111);editor.setHintTextColor(0xff7a756b);editor.setHint("Type here");editor.setBackgroundColor(Color.TRANSPARENT);editor.setGravity(Gravity.TOP);editor.setPadding(10,8,10,8);editor.setMinHeight(64);editor.setTextSize(TypedValue.COMPLEX_UNIT_PX,font);editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);editor.setHorizontallyScrolling(false);editor.setSelectAllOnFocus(false);editor.setText(value);editor.setFilters(new InputFilter[]{(source,start,end,dest,dstart,dend)->{int room=50000-totalText(block)-(dest.length()-(dend-dstart));if(room<=0)return "";return end-start<=room?null:source.subSequence(start,start+room);}});blocks.add(block);paper.addView(editor);layoutBlock(block);editor.setOnFocusChangeListener((view,focused)->{if(focused){selected=block;paper.invalidate();}});editor.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){if(!loading&&SystemClock.uptimeMillis()-typedCheckpoint>800){checkpoint();typedCheckpoint=SystemClock.uptimeMillis();}}public void onTextChanged(CharSequence s,int a,int b,int c){if(!loading)mark();}public void afterTextChanged(Editable text){}});}
 void layoutBlock(Block block){FrameLayout.LayoutParams size=new FrameLayout.LayoutParams(Math.round(block.width),-2);size.leftMargin=Math.round(block.x);size.topMargin=Math.round(block.y);block.editor.setLayoutParams(size);block.editor.setTextSize(TypedValue.COMPLEX_UNIT_PX,block.font);}
 void mark(){if(loading)return;paper.post(()->grow());paper.invalidate();changed.run();}
 void grow(){int needed=1600;for(Block block:blocks)needed=Math.max(needed,(int)(block.y+block.editor.getHeight()+160));if(needed>height){height=Math.min(200000,((needed+399)/400)*400);resize();}}
 protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);resize();}
 void resize(){if(getWidth()<=0)return;scale=getWidth()/1000f*zoom;int width=Math.max(1,Math.round(1000*scale)),pixels=Math.max(1,Math.round(height*scale));paper.setScaleX(scale);paper.setScaleY(scale);paper.setLayoutParams(new FrameLayout.LayoutParams(1000,height));extent.setLayoutParams(new ScrollView.LayoutParams(width,pixels));vertical.setLayoutParams(new HorizontalScrollView.LayoutParams(Math.max(getWidth(),width),-1));paper.invalidate();}
 void zoom(float factor){zoom=clamp(zoom*factor,.5f,3);resize();}
 void setTool(int tool){mode=tool;for(Block block:blocks){if(tool!=TEXT)block.editor.clearFocus();block.editor.setFocusableInTouchMode(tool==TEXT);block.editor.setFocusable(tool==TEXT);block.editor.setCursorVisible(tool==TEXT);}if(tool!=TEXT){((InputMethodManager)host.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(getWindowToken(),0);paper.setFocusableInTouchMode(true);paper.requestFocus();}paper.invalidate();}
 void checkpoint(){if(loading)return;try{String value=json();if(value.length()>600000)return;if(!undo.isEmpty()&&undo.peekLast().equals(value))return;undo.addLast(value);int size=0;for(String entry:undo)size+=entry.length();while(undo.size()>12||size>600000)size-=undo.removeFirst().length();redo.clear();}catch(Exception error){host.toast("Undo snapshot unavailable");}}
 void history(boolean forward){ArrayDeque<String> from=forward?redo:undo,to=forward?undo:redo;if(from.isEmpty())return;try{String current=json(),next=from.removeLast();to.addLast(current);restore(new JSONObject(next));setTool(mode);mark();}catch(Exception error){host.toast("Cannot restore notebook step");}}
 void format(String kind){if(selected==null){host.toast("Select a text box first");return;}EditText editor=selected.editor;int a=Math.max(0,editor.getSelectionStart()),b=Math.max(a,editor.getSelectionEnd());if(a==b){host.toast("Select text to format");return;}checkpoint();Object span=kind.equals("b")?new StyleSpan(Typeface.BOLD):kind.equals("i")?new StyleSpan(Typeface.ITALIC):kind.equals("u")?new UnderlineSpan():new RelativeSizeSpan(1.35f);editor.getText().setSpan(span,a,b,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);mark();}
 void prefix(String prefix){if(selected==null){host.toast("Select a text box first");return;}EditText editor=selected.editor;int at=Math.max(0,editor.getSelectionStart()),start=editor.getText().toString().lastIndexOf('\n',Math.max(0,at-1))+1;editor.getText().insert(start,prefix);}
 void adjust(int action){if(selected==null){host.toast("Select a text box first");return;}checkpoint();if(action==4){paper.removeView(selected.editor);blocks.remove(selected);selected=null;}else{if(action==0||action==1)selected.width=clamp(selected.width+(action==0?80:-80),180,1000-selected.x);else selected.font=clamp(selected.font+(action==2?6:-6),16,160);layoutBlock(selected);}mark();}
 String json()throws JSONException{JSONObject doc=new JSONObject().put("v",1).put("width",1000).put("height",height);JSONArray text=new JSONArray(),ink=new JSONArray();StringBuilder plain=new StringBuilder();for(Block block:blocks){String value=host.encodeNote(block.editor.getText());text.put(new JSONObject().put("x",block.x).put("y",block.y).put("width",block.width).put("font",block.font).put("value",value));if(plain.length()>0)plain.append('\n');plain.append(block.editor.getText());}for(Stroke stroke:strokes){JSONArray points=new JSONArray();for(PointF point:stroke.points){points.put(Math.round(point.x*10)/10.0);points.put(Math.round(point.y*10)/10.0);}ink.put(new JSONObject().put("color",stroke.color).put("width",stroke.width).put("points",points));}doc.put("text",plain.toString()).put("blocks",text).put("strokes",ink);if(original!=null)doc.put("legacy",original);return doc.toString();}
 void restore(JSONObject doc)throws Exception{if(doc.getInt("v")!=1||doc.getInt("width")!=1000)throw new Exception("Unknown notebook format");int newHeight=doc.getInt("height");JSONArray text=doc.getJSONArray("blocks"),ink=doc.getJSONArray("strokes");if(newHeight<1600||newHeight>200000||text.length()>80||ink.length()>600)throw new Exception("Notebook limits exceeded");loading=true;try{paper.removeAllViews();blocks.clear();strokes.clear();selected=null;activeStroke=null;pointCount=0;height=newHeight;original=doc.optJSONObject("legacy");int length=0;for(int i=0;i<text.length();i++){JSONObject item=text.getJSONObject(i);float x=(float)item.getDouble("x"),y=(float)item.getDouble("y"),width=(float)item.getDouble("width"),font=(float)item.getDouble("font");CharSequence value=host.decodeNote(item.getString("value"));length+=value.length();if(!valid(x)||!valid(y)||!valid(width)||!valid(font)||x<0||y<0||y>height||width<180||x+width>1001||font<16||font>160||length>50000)throw new Exception("Invalid text box");addBlock(x,y,width,font,value);}for(int i=0;i<ink.length();i++){JSONObject item=ink.getJSONObject(i);float width=(float)item.getDouble("width");if(!valid(width)||width<.1f||width>100)throw new Exception("Invalid ink width");Stroke stroke=new Stroke(item.getInt("color"),width);JSONArray points=item.getJSONArray("points");if(points.length()<2||points.length()%2!=0)throw new Exception("Invalid ink points");for(int n=0;n<points.length();n+=2){float x=(float)points.getDouble(n),y=(float)points.getDouble(n+1);if(!valid(x)||!valid(y)||x<0||x>1000||y<0||y>height||++pointCount>12000)throw new Exception("Invalid ink points");stroke.points.add(new PointF(x,y));}strokes.add(stroke);}}finally{loading=false;}resize();paper.invalidate();}
 Block at(float x,float y){for(int i=blocks.size()-1;i>=0;i--){Block block=blocks.get(i);if(new RectF(block.x,block.y,block.x+block.width,block.y+block.editor.getHeight()).contains(x,y))return block;}return null;}
 class Document extends FrameLayout{final Paint pen=new Paint(3);float downX,downY,lastX,lastY;boolean moved=false,penGesture=false,moving=false;Document(){super(host);setWillNotDraw(false);setClipChildren(false);}protected void onLayout(boolean changed,int l,int t,int r,int b){super.onLayout(changed,l,t,r,b);post(()->grow());}protected void onDraw(Canvas canvas){canvas.drawColor(Color.WHITE);pen.setStyle(Paint.Style.STROKE);pen.setStrokeWidth(1);pen.setColor(0xffe4e8ec);for(int y=48;y<height;y+=48)canvas.drawLine(0,y,1000,y,pen);if(selected!=null&&mode==MOVE){pen.setColor(0xff6a8192);pen.setStrokeWidth(2);canvas.drawRect(selected.x,selected.y,selected.x+selected.width,selected.y+selected.editor.getHeight(),pen);}}protected void dispatchDraw(Canvas canvas){super.dispatchDraw(canvas);legacy.draw(canvas,new RectF(0,0,1000,1400));pen.setStrokeCap(Paint.Cap.ROUND);pen.setStrokeJoin(Paint.Join.ROUND);for(Stroke stroke:strokes){pen.setColor(stroke.color);pen.setStrokeWidth(stroke.width);if(stroke.points.size()==1){pen.setStyle(Paint.Style.FILL);PointF point=stroke.points.get(0);canvas.drawCircle(point.x,point.y,stroke.width/2,pen);}else{pen.setStyle(Paint.Style.STROKE);Path path=new Path();boolean first=true;for(PointF point:stroke.points){if(first){path.moveTo(point.x,point.y);first=false;}else path.lineTo(point.x,point.y);}canvas.drawPath(path,pen);}}}
 public boolean onInterceptTouchEvent(MotionEvent event){if(penGesture||moving)return true;boolean stylus=event.getPointerCount()>0&&event.getToolType(0)==MotionEvent.TOOL_TYPE_STYLUS;return mode==PEN||mode==HIGHLIGHT||(stylus&&mode==TEXT)||(mode==MOVE&&at(event.getX(),event.getY())!=null);}
 void point(float x,float y){if(activeStroke==null||pointCount>=12000)return;activeStroke.points.add(new PointF(clamp(x,0,1000),clamp(y,0,height)));pointCount++;}
 public boolean onTouchEvent(MotionEvent event){int action=event.getActionMasked();float x=event.getX(),y=event.getY();if(event.getPointerCount()>1){if(activeStroke!=null){pointCount-=activeStroke.points.size();strokes.remove(activeStroke);activeStroke=null;}penGesture=moving=false;getParent().requestDisallowInterceptTouchEvent(false);invalidate();return true;}if(action==MotionEvent.ACTION_DOWN){downX=lastX=x;downY=lastY=y;moved=false;boolean stylus=event.getToolType(0)==MotionEvent.TOOL_TYPE_STYLUS;penGesture=mode==PEN||mode==HIGHLIGHT||(stylus&&mode==TEXT);moving=mode==MOVE;if(mode==SCROLL)return false;if(penGesture){getParent().requestDisallowInterceptTouchEvent(true);if(strokes.size()>=600||pointCount>=12000){penGesture=false;host.toast("Drawing limit reached / undo or use another note");return true;}checkpoint();activeStroke=new Stroke(mode==HIGHLIGHT?0x55ffcf33:0xff245cb3,clamp(host.dp(mode==HIGHLIGHT?18:3)/Math.max(.01f,scale),.1f,100));strokes.add(activeStroke);point(x,y);}else if(moving){selected=at(x,y);if(selected==null)return false;checkpoint();getParent().requestDisallowInterceptTouchEvent(true);}return true;}if(action==MotionEvent.ACTION_MOVE){if(Math.abs(x-downX)+Math.abs(y-downY)>12)moved=true;if(penGesture){for(int i=0;i<event.getHistorySize();i++)point(event.getHistoricalX(i),event.getHistoricalY(i));point(x,y);}else if(moving&&selected!=null){selected.x=clamp(selected.x+x-lastX,0,1000-selected.width);selected.y=clamp(selected.y+y-lastY,0,height-64);layoutBlock(selected);}lastX=x;lastY=y;}else if(action==MotionEvent.ACTION_UP){if(penGesture||moving){activeStroke=null;mark();}else if(mode==TEXT&&!moved){if(blocks.size()>=80){host.toast("Text-box limit reached");return true;}checkpoint();float bx=clamp(x,0,800),by=clamp(y,0,height-80),font=clamp(18*getResources().getDisplayMetrics().scaledDensity/Math.max(.01f,scale),28,80);addBlock(bx,by,Math.min(520,1000-bx),font,"");selected=blocks.get(blocks.size()-1);EditText editor=selected.editor;editor.post(()->{editor.requestFocus();((InputMethodManager)host.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(editor,InputMethodManager.SHOW_IMPLICIT);});mark();}penGesture=moving=false;getParent().requestDisallowInterceptTouchEvent(false);performClick();}else if(action==MotionEvent.ACTION_CANCEL){if(activeStroke!=null){pointCount-=activeStroke.points.size();strokes.remove(activeStroke);activeStroke=null;}penGesture=moving=false;getParent().requestDisallowInterceptTouchEvent(false);}invalidate();return true;}public boolean performClick(){super.performClick();return true;}}
